import {escapeHtml as esc,icon,formatDate} from '../ui.js';
import {deviceCatalog,searchCatalog,catalogCategories} from '../connections/catalog.js';

const catalogName=entry=>entry.name||`${entry.manufacturer} ${entry.model}`;
const categoryName=value=>String(value).replaceAll('_',' ').replaceAll('-',' ').replace(/\b\w/g,char=>char.toUpperCase());
const time=value=>value?`${formatDate(value,{short:true,time:true})}, ${new Date(value).getFullYear()}`:'Not available';

function streamPanel(ctx) {
  const bt=ctx.connectionUI.bluetooth;
  const sample=bt.latestSample;
  const value=sample?.bpm;
  const profile=sample?.kind||bt.profile;
  const numeric=value=>Number.isFinite(value)?Number(value).toLocaleString('en-US',{maximumFractionDigits:1}):'—';
  const reading=profile==='blood_pressure'?`${numeric(sample?.systolic)} / ${numeric(sample?.diastolic)}`:profile==='pulse_oximeter'?numeric(sample?.spo2):numeric(value);
  const unit=profile==='blood_pressure'?(sample?.unit||'mmHg'):profile==='pulse_oximeter'?'%':profile==='heart_rate'?'bpm':'';
  const label=profile==='blood_pressure'?'Blood pressure':profile==='pulse_oximeter'?'Oxygen saturation':profile==='heart_rate'?'Live heart rate':'Device reading';
  const samples=bt.samples||[];
  const receiving=bt.status==='receiving';
  return `<section class="bluetooth-panel" aria-labelledby="bluetooth-title"><div class="bluetooth-intro"><span class="connection-symbol">${icon('activity',26)}</span><div><h2 id="bluetooth-title">Bring your next reading into focus.</h2><p>Pair a monitor using a standard Bluetooth Heart Rate, Blood Pressure, or Pulse Oximeter service.</p></div></div><div class="bluetooth-session"><div class="live-reading"><span>${bt.latestSampleStale?(['unusable_measurement','invalid_measurement'].includes(bt.errorCode)?'Previous reading · Latest measurement rejected':'Previous reading · Disconnected'):esc(label)}</span><strong class="${profile==='blood_pressure'?'pressure-reading':''}">${esc(reading)} <small>${esc(unit)}</small></strong><span>${bt.device?esc(bt.device.name||'Selected health monitor'):'Choose your nearby health monitor'}</span></div><div class="bluetooth-status"><span class="connection-status ${receiving?'is-receiving':''}">${esc(categoryName(bt.status))}</span><p id="bluetooth-message" role="status">${esc(bt.message||'Your browser will ask you to choose a compatible monitor.')}</p>${(sample?.qualityWarnings||[]).map(warning=>`<p class="sensor-note">${esc(warning)}</p>`).join('')}${sample?.pulseRate!=null?`<p>Pulse: ${numeric(sample.pulseRate)} bpm</p>`:''}${sample?.contactDetected===false?'<p class="sensor-note">Sensor contact was not detected. Check the fit before using this reading.</p>':''}${bt.latestSample?`<p class="muted">Latest reading: ${esc(time(bt.latestSample.timestamp||bt.latestSample.observedAt))} · ${samples.length} retained readings${bt.totalSamples>samples.length?` of ${bt.totalSamples} received`:""}</p>`:''}<div class="button-row">${bt.connected?'<button class="button" data-bluetooth-disconnect>Disconnect</button>':`<button class="button primary" data-bluetooth-connect ${!bt.available||bt.status==='connecting'?'disabled':''}>${bt.status==='connecting'?'Connecting…':'Find nearby monitors'} ${icon('connect',16)}</button>`}${samples.length?'<button class="button" data-bluetooth-download>Download readings</button>':''}</div></div></div><p class="connection-footnote">Readings stay in this browser session. Heart rate is separate from resting heart rate and ECG. Supported standards do not guarantee compatibility with every model. ${!bt.available?'Open this page in Chrome or Edge on a supported computer, or Chrome on Android, to pair.':'Keep your monitor awake and nearby; disconnect it from other apps if it cannot be found.'}</p></section>`;
}

function connectedSources(ctx) {
  const local=ctx.workspace.mode==='local';
  return `<section class="connected-history" aria-labelledby="connected-history-title"><div class="section-title"><div><h2 id="connected-history-title">Your connected history</h2><p class="muted">${local?'Read from the history already synchronized by your Health app.':'Connect your local Health app to bring Google Health and Lyfta history into this workspace.'}</p></div>${local?`<button class="button" data-refresh-workspace ${ctx.connectionUI.refreshing?'disabled':''}>${icon('reset',15)}${ctx.connectionUI.refreshing?'Refreshing…':'Refresh history'}</button>`:'<a class="button" href="http://127.0.0.1:4173/?screen=connect">Open local workspace '+icon('arrow',16)+'</a>'}</div><div class="connected-source-list">${['google-health','lyfta'].map(id=>{
    const source=ctx.sources.find(item=>item.id===id),available=source?.status==='connected';
    const records=ctx.workspace.events.filter(event=>event.sourceId===id).length;
    const workouts=id==='lyfta'?ctx.workspace.workouts.length:0;
    return `<article class="connected-source-row"><span class="registry-icon">${icon(id==='lyfta'?'activity':'source',25)}</span><div class="connected-source-copy"><h3>${id==='lyfta'?'Lyfta':'Google Health'}</h3><p class="muted">${esc(source?.description||(id==='lyfta'?'Your saved workouts, exercises and completed sets.':'Your synchronized sleep, steps and resting heart rate.'))}</p><span class="connection-status">${available?'Local history connected':'Not connected here'}</span>${available?`<small>Last sync: ${esc(time(source.lastSyncedAt))}</small>`:''}</div><div class="connected-source-action">${available?`<strong>${id==='lyfta'?workouts:records} ${id==='lyfta'?'workouts':'daily measurements'}</strong><button class="button" data-view-source="${id}">View ${id==='lyfta'?'workouts':'records'} ${icon('arrow',16)}</button>`:'<a class="button" href="http://localhost:3000" target="_blank" rel="noopener noreferrer">Set up in Health app '+icon('arrow',16)+'</a>'}</div></article>`;
  }).join('')}</div><p class="connection-footnote">${local?'Refresh reads the latest saved history. Manage account authorization and synchronization in your existing Health app.':'Your personal history stays on your computer. The public website does not publish or share it.'} <a href="http://localhost:3000" target="_blank" rel="noopener noreferrer">Open Health app</a></p>${ctx.workspace.notices?.length?`<details class="history-method"><summary>How your history is read</summary>${ctx.workspace.notices.map(note=>`<p class="connection-notice">${esc(typeof note==='string'?note:note.message||'')}</p>`).join('')}</details>`:''}</section>`;
}

function deviceDetails(entry,ctx) {
  if(!entry)return '';
  const tryProfile={'heart-rate':'heart_rate','blood-pressure':'blood_pressure','pulse-oximeter':'pulse_oximeter'}[entry.category];
  const steps=Array.isArray(entry.setup)?entry.setup:[entry.setup].filter(Boolean);
  return `<section class="device-detail panel" id="device-detail" tabindex="-1" aria-labelledby="device-detail-title"><div class="section-title"><div><span class="device-manufacturer">${esc(entry.manufacturer)}</span><h2 id="device-detail-title">${esc(catalogName(entry))}</h2></div><button class="button subtle" data-device-close aria-label="Close device details">${icon('close',18)}</button></div><span class="connection-status">${esc(categoryName(entry.supportStatus||entry.connectionMethod))}</span><p>${esc(entry.description)}</p>${steps.length?`<ol class="device-setup">${steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol>`:''}<div class="button-row">${entry.canConnect?`<button class="button primary" data-bluetooth-connect="${esc(entry.id)}" ${!ctx.connectionUI.bluetooth.available||ctx.connectionUI.bluetooth.status==='connecting'?'disabled':''}>Find compatible device ${icon('connect',16)}</button>`:tryProfile?`<button class="button" data-bluetooth-profile="${tryProfile}" ${!ctx.connectionUI.bluetooth.available?'disabled':''}>Check Bluetooth support ${icon('connect',16)}</button>`:''}${entry.manufacturerUrl?`<a class="button" href="${esc(entry.manufacturerUrl)}" target="_blank" rel="noopener noreferrer">Manufacturer setup ${icon('arrow',16)}</a>`:''}</div><p class="connection-footnote">${entry.canConnect?'The browser chooser filters by the advertised measurement service. A catalog listing does not verify this exact model or firmware.':tryProfile?'A product-specific integration is not implemented. Check Bluetooth support to see whether your device advertises the standard measurement service; if it does not appear, use the manufacturer’s setup.':'This connection method needs its own integration. Selecting this product does not pair it or import measurements.'}</p></section>`;
}

export async function renderConnect(ctx) {
  const ui=ctx.connectionUI;
  const results=searchCatalog(ui.query,{category:ui.category==='all'?undefined:ui.category});
  const categories=[...new Set(deviceCatalog.map(entry=>entry.category))];
  const selected=deviceCatalog.find(entry=>entry.id===ui.selectedDevice);
  return `<div class="connections-workspace"><div class="connections-shortcuts"><button class="button" data-connection-jump="connected-history-title">Your sources ${icon('source',16)}</button><button class="button" data-connection-jump="bluetooth-title">Pair nearby ${icon('connect',16)}</button></div><section class="device-library" aria-labelledby="device-library-title"><div class="section-title"><div><h2 id="device-library-title">Find your device.</h2><p class="muted">Search a brand, model, or measurement. See how it can connect before you start.</p></div><span class="pill">${deviceCatalog.length} connection guides</span></div><label class="catalog-search-label" for="device-search">Device or manufacturer</label><div class="catalog-search"><span>${icon('connect',20)}</span><input type="search" id="device-search" autocomplete="off" placeholder="Try Polar H10, Kardia, ECG…" value="${esc(ui.query)}" aria-controls="device-results"></div><div class="catalog-categories" role="group" aria-label="Device category">${['all',...categories].map(category=>`<button class="${ui.category===category?'selected':''}" data-device-category="${esc(category)}" aria-pressed="${ui.category===category}">${esc(catalogCategories.find(item=>item.id===category)?.label||categoryName(category))}</button>`).join('')}</div>${deviceDetails(selected,ctx)}<p id="device-result-count" class="muted" aria-live="polite">${results.length} ${results.length===1?'match':'matches'}${ui.query?` for “${esc(ui.query)}”`:''}</p><div class="device-results" id="device-results" role="region" aria-label="Device catalog results" tabindex="0">${results.length?results.map(entry=>`<article class="device-row"><span class="device-kind-icon">${icon(entry.category.includes('heart')||entry.category.includes('ecg')?'heart':'connect',23)}</span><div class="device-copy"><span class="device-manufacturer">${esc(entry.manufacturer)}</span><h3>${esc(catalogName(entry))}</h3><p>${esc(entry.description)}</p><span class="device-method">${esc(entry.supportStatus)}</span></div><button class="button" data-device-id="${esc(entry.id)}" aria-label="View connection details for ${esc(catalogName(entry))}">Details ${icon('arrow',16)}</button></article>`).join(''):'<div class="catalog-empty"><h3>No matching device yet.</h3><p>Try the manufacturer name or a measurement such as ECG. A device that broadcasts the standard Heart Rate service can still appear in the nearby-monitor chooser above.</p><button class="button" data-device-clear>Clear search</button></div>'}</div><p class="connection-footnote">This is a curated compatibility catalog, not a list of devices detected nearby. Proprietary ECG, glucose, and other device protocols require their own supported integration.</p></section>${connectedSources(ctx)}${streamPanel(ctx)}</div>`;
}
